-- Judge-friendly proof that spatial + distributed vector memory are live.
SELECT id, name, region, combined_risk
FROM locations
ORDER BY combined_risk DESC
LIMIT 5;

SELECT title, hazard,
       embedding <-> '[0.17192268,-0.52131393,0.16083089,0.00000000,0.14419322,0.03327536,0.14973911,0.00000000,0.00000000,0.16083089,0.00000000,0.00000000,-0.14973911,0.16637679,-0.14419322,0.00000000,-0.32166179,0.00000000,0.00000000,0.16083089,-0.33275357,-0.14973911,0.28838643,0.19410625,0.00000000,0.00000000,0.14419322,0.32166179,0.00000000,0.00000000,0.00554589,-0.15528500]'::VECTOR AS l2_distance,
       1 - power(embedding <-> '[0.17192268,-0.52131393,0.16083089,0.00000000,0.14419322,0.03327536,0.14973911,0.00000000,0.00000000,0.16083089,0.00000000,0.00000000,-0.14973911,0.16637679,-0.14419322,0.00000000,-0.32166179,0.00000000,0.00000000,0.16083089,-0.33275357,-0.14973911,0.28838643,0.19410625,0.00000000,0.00000000,0.14419322,0.32166179,0.00000000,0.00000000,0.00554589,-0.15528500]'::VECTOR, 2) / 2 AS cosine_similarity
FROM agent_memories
WHERE hazard = 'fire'
ORDER BY embedding <-> '[0.17192268,-0.52131393,0.16083089,0.00000000,0.14419322,0.03327536,0.14973911,0.00000000,0.00000000,0.16083089,0.00000000,0.00000000,-0.14973911,0.16637679,-0.14419322,0.00000000,-0.32166179,0.00000000,0.00000000,0.16083089,-0.33275357,-0.14973911,0.28838643,0.19410625,0.00000000,0.00000000,0.14419322,0.32166179,0.00000000,0.00000000,0.00554589,-0.15528500]'::VECTOR
LIMIT 3;

SELECT index_name, create_statement
FROM crdb_internal.table_indexes
WHERE descriptor_name = 'agent_memories'
  AND create_statement LIKE 'CREATE VECTOR INDEX%'
ORDER BY index_name;

EXPLAIN SELECT id, title
FROM agent_memories
WHERE hazard = 'fire'
ORDER BY embedding <-> '[0.17192268,-0.52131393,0.16083089,0.00000000,0.14419322,0.03327536,0.14973911,0.00000000,0.00000000,0.16083089,0.00000000,0.00000000,-0.14973911,0.16637679,-0.14419322,0.00000000,-0.32166179,0.00000000,0.00000000,0.16083089,-0.33275357,-0.14973911,0.28838643,0.19410625,0.00000000,0.00000000,0.14419322,0.32166179,0.00000000,0.00000000,0.00554589,-0.15528500]'::VECTOR
LIMIT 3;

SELECT id, location_id, provider, status, combined_risk, confidence, created_at
FROM satellite_assessments
ORDER BY created_at DESC
LIMIT 5;
